// CodeJS1 (Run Once for All Items)

// 1) Kaynakları doğru yerden al
const genelResp = $('genel bilgiler').first().json;   // HTTP response object
const detayResp = $('portföy dağılımı').first().json;

const genelList = genelResp?.resultList ?? genelResp?.data?.resultList ?? [];
const detayList = detayResp?.resultList ?? detayResp?.data?.resultList ?? [];

// 2) Tarih: json içinden alıp dd.mm.yyyy yap
function toDDMMYYYY(iso) {
  if (!iso) return null;
  const s = String(iso).trim();
  const m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (m) return `${m[3]}.${m[2]}.${m[1]}`;
  const m2 = s.match(/^(\d{2})\.(\d{2})\.(\d{4})$/);
  if (m2) return s;
  return null;
}

// 3) Genel liste boşsa bile 1 item döndür (workflow durmasın)
if (!Array.isArray(genelList) || genelList.length === 0) {
  return [{
    json: {
      _skip: true,
      reason: 'genelList boş geldi (eski veriler2 resultList yok)',
      genelKeys: Object.keys(genelResp || {}),
      detayKeys: Object.keys(detayResp || {})
    }
  }];
}

// 4) Birleştir
const birlesik = genelList.map(genel => {
  const code = (genel?.fonKodu ?? genel?.FONKODU ?? '').toString().trim();

  const detay = (Array.isArray(detayList) ? detayList : []).find(d => {
    const dcode = (d?.fonKodu ?? d?.FONKODU ?? '').toString().trim();
    return code && dcode && code === dcode;
  }) || {};

  const sql_tarih = toDDMMYYYY(genel?.tarih ?? detay?.tarih);

  return {
    json: {
      ...genel,
      ...detay,
      sql_tarih,
      fonKodu: code
    }
  };
});

return birlesik;

// SQL CODER (Run Once for All Items)

const results = [];

function esc(v) {
  return String(v ?? '').replace(/\\/g, '\\\\').replace(/'/g, "''");
}

function num(v, def = 'NULL') {
  if (v === null || v === undefined || v === '' || v === 'NULL') return def;
  const s = String(v).replace(',', '.');
  const n = Number(s);
  return Number.isFinite(n) ? String(n) : def;
}

function str(v) {
  if (v === null || v === undefined || v === '' || v === 'NULL') return 'NULL';
  return `'${esc(v)}'`;
}

// bazı field'lar farklı isimle gelebilir -> getter
function get(j, ...keys) {
  for (const k of keys) {
    if (j && Object.prototype.hasOwnProperty.call(j, k)) return j[k];
  }
  return undefined;
}

for (const item of $input.all()) {
  const j = item.json;

  const code = (get(j, 'fonKodu', 'FONKODU', 'code') ?? '').toString().trim();
  const sql_tarih = get(j, 'sql_tarih'); // CodeJS1 bunu dd.mm.yyyy yaptı

  const query = `
INSERT INTO tefas_fund_details (
  code, tarih, FIYAT, TEDPAYSAYISI, KISISAYISI, PORTFOYBUYUKLUK, BORSABULTENFIYAT,
  BB, BPP, BYF, D, DB, DT, DÖT, EUT, FB, FKB, GAS, GSYKB, GSYY, GYKB, GYY, HB, HS,
  KBA, KH, KHAU, KHD, KHTL, KKS, KKSD, KKSTL, KKSYD, KM, KMBYF, KMKBA, KMKKS, KİBD,
  OSKS, OST, R, T, TPP, TR, VDM, VM, VMAU, VMD, VMTL, VİNT, YBA, YBKB, YBOSB, YBYF,
  YHS, YMK, YYF, ÖKSYD, ÖSDB, BilFiyat
)
SELECT
  TRIM('${esc(code)}'),
  STR_TO_DATE('${esc(sql_tarih)}', '%d.%m.%Y'),

  ${num(get(j, 'fiyat', 'FIYAT'), '0')},
  ${num(get(j, 'tedPaySayisi', 'TEDPAYSAYISI'), '0')},
  ${num(get(j, 'kisiSayisi', 'KISISAYISI'), '0')},
  ${num(get(j, 'portfoyBuyukluk', 'PORTFOYBUYUKLUK'), '0')},
  ${str(get(j, 'borsaBultenFiyat', 'BORSABULTENFIYAT'))},

  ${num(get(j,'bb','BB'))}, ${num(get(j,'bpp','BPP'))}, ${num(get(j,'byf','BYF'))},
  ${num(get(j,'d','D'))},  ${num(get(j,'db','DB'))},  ${num(get(j,'dt','DT'))},
  ${num(get(j,'dot','DÖT','döt'))}, ${num(get(j,'eut','EUT'))}, ${num(get(j,'fb','FB'))},
  ${num(get(j,'fkb','FKB'))}, ${num(get(j,'gas','GAS'))}, ${num(get(j,'gsykb','GSYKB'))},
  ${num(get(j,'gsyy','GSYY'))}, ${num(get(j,'gykb','GYKB'))}, ${num(get(j,'gyy','GYY'))},
  ${num(get(j,'hb','HB'))}, ${num(get(j,'hs','HS'))},

  ${num(get(j,'kba','KBA'))}, ${num(get(j,'kh','KH'))}, ${num(get(j,'khau','KHAU'))},
  ${num(get(j,'khd','KHD'))}, ${num(get(j,'khtl','KHTL'))}, ${num(get(j,'kks','KKS'))},
  ${num(get(j,'kksd','KKSD'))}, ${num(get(j,'kkstl','KKSTL'))}, ${num(get(j,'kksyd','KKSYD'))},
  ${num(get(j,'km','KM'))}, ${num(get(j,'kmbyf','KMBYF'))}, ${num(get(j,'kmkba','KMKBA'))},
  ${num(get(j,'kmkks','KMKKS'))},
  ${num(get(j,'kibd','KİBD'))},

  ${num(get(j,'osks','OSKS'))}, ${num(get(j,'ost','OST'))}, ${num(get(j,'r','R'))},
  ${num(get(j,'t','T'))}, ${num(get(j,'tpp','TPP'))},
  ${num(get(j,'tr','TR'))},

  ${num(get(j,'vdm','VDM'))}, ${num(get(j,'vm','VM'))}, ${num(get(j,'vmau','VMAU'))},
  ${num(get(j,'vmd','VMD'))}, ${num(get(j,'vmtl','VMTL'))},
  ${num(get(j,'vint','VİNT'))},

  ${num(get(j,'yba','YBA'))}, ${num(get(j,'ybkb','YBKB'))}, ${num(get(j,'ybosb','YBOSB'))},
  ${num(get(j,'ybyf','YBYF'))}, ${num(get(j,'yhs','YHS'))}, ${num(get(j,'ymk','YMK'))},
  ${num(get(j,'yyf','YYF'))},

  ${num(get(j,'oksyd','ÖKSYD'))},
  ${num(get(j,'osdb','ÖSDB'))},

  ${num(get(j,'bilFiyat','BilFiyat'), '0')}
FROM DUAL
WHERE EXISTS (
  SELECT 1
  FROM tefas_funds f
  WHERE f.code = TRIM('${esc(code)}')
)
ON DUPLICATE KEY UPDATE
  FIYAT = VALUES(FIYAT),
  PORTFOYBUYUKLUK = VALUES(PORTFOYBUYUKLUK),
  KISISAYISI = VALUES(KISISAYISI),
  TEDPAYSAYISI = VALUES(TEDPAYSAYISI),
  BilFiyat = VALUES(BilFiyat);
`.trim();

  results.push({ json: { query } });
}

return results;
